export type IntentEnginePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function intentEngineProgram() {
  return <T extends IntentEnginePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { intentEngine: IntentEnginePlugin }> => {
    return extendClient(client, {
      intentEngine: {
        accounts: {
          config: addSelfFetchFunctions(client, getConfigCodec()),
          intent: addSelfFetchFunctions(client, getIntentCodec()),
          mandate: addSelfFetchFunctions(client, getMandateCodec()),
          mintCap: addSelfFetchFunctions(client, getMintCapCodec()),
          userState: addSelfFetchFunctions(client, getUserStateCodec()),
        },
        instructions: {
          acceptAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptAdminInstruction(input),
            ),
          advanceEpoch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdvanceEpochInstructionAsync(input),
            ),
          advanceNonce: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdvanceNonceInstructionAsync(input),
            ),
          beginFill: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBeginFillInstructionAsync(input),
            ),
          cancelIntent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelIntentInstructionAsync(input),
            ),
          closeIntent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseIntentInstructionAsync(input),
            ),
          createIntent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateIntentInstructionAsync(input),
            ),
          createIntentByAgent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateIntentByAgentInstructionAsync(input),
            ),
          createIntentSigned: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateIntentSignedInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          createMandate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMandateInstructionAsync(input),
            ),
          endFill: (input) =>
            addSelfPlanAndSendFunctions(client, getEndFillInstruction(input)),
          expireIntent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExpireIntentInstructionAsync(input),
            ),
          fillAttested: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillAttestedInstructionAsync(input),
            ),
          fillAttestedSplit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillAttestedSplitInstructionAsync(input),
            ),
          fillIntent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillIntentInstructionAsync(input),
            ),
          initConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitConfigInstructionAsync(input),
            ),
          initUser: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitUserInstructionAsync(input),
            ),
          lowerPause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLowerPauseInstruction(input),
            ),
          proposeAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeAdminInstruction(input),
            ),
          raisePause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRaisePauseInstruction(input),
            ),
          revokeMandate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeMandateInstruction(input),
            ),
          setCapsRequired: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetCapsRequiredInstruction(input),
            ),
          setMintCap: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMintCapInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          updateConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateConfigInstruction(input),
            ),
          updateEconomics: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateEconomicsInstruction(input),
            ),
        },
        pdas: {
          userState: findUserStatePda,
          vault: findVaultPda,
          mintCap: findMintCapPda,
          delegate: findDelegatePda,
          config: findConfigPda,
          setMintCapMintCap: findSetMintCapMintCapPda,
        },
        identifyAccount: identifyIntentEngineAccount,
        identifyInstruction: identifyIntentEngineInstruction,
        parseInstruction: parseIntentEngineInstruction,
      } as IntentEnginePlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
